examples.code:
MonarchEmojiPicker(
    categories: [
        MonarchEmojiPickerCategory(
            id: "status",
            label: "Status",
            emojis: [
                MonarchEmojiPickerItem("✅", name: "done", keywords: ["complete"]),
                MonarchEmojiPickerItem("🚧", name: "in progress"),
                MonarchEmojiPickerItem("⛔", name: "blocked"),
            ]
        )
    ],
    showsSkinTones: false
) { _, item in
    status = item.name
}
